+static const range_string qos_mgmt_attributes[] = {
+  { 0, 0, "Reserved" },
+  { 1, 1, "DSCP Management Capabilities" },
+  { 2, 2, "DSCP Policy" },
+  { 3, 3, "TCLAS" },
